def transform(grid):
    g = [row[:] for row in grid]
    pts = [(r, c) for r, row in enumerate(g) for c, v in enumerate(row) if v == 4]
    cmin = min(c for r, c in pts)
    for r, c in pts:
        nc = 2 * cmin - 1 - c
        if nc >= 0:
            g[r][nc] = 4
    for r, row in enumerate(g):
        for c, value in enumerate(row):
            if value == 6:
                g[r][c] = 0
    return g
